import foodLibraryJson from '../data/food_library.json'

// ===== 类型定义 =====
export interface FoodBase {
  id: string
  name: string
  cat: string
  kcal: number          // 每 100g / 100ml 热量
  unit: string          // g 或 ml
  protein?: number      // g / 100g|ml
  carb?: number
  fat?: number
  pieceWeight?: number  // 按个计食物的克重
  vessel?: string
  opts?: string[]
  img?: string
  conf?: number
}

export interface VesselTplEntry {
  k: string
  name: string
  amount: number
  unit: string
}

export interface VesselTpl {
  label: string
  sizes: VesselTplEntry[]
}

export interface SweetTpl {
  label: string
  options: OptItem[]
}

export interface OptItem {
  k: string
  name: string
  deltaKcal: number
}

export interface FoodEntry {
  id: string
  name: string
  kcal: number
  protein: number
  carb: number
  fat: number
  ts: number
  meal: string
}

export interface MealRow {
  key: string
  label: string
  entries: FoodEntry[]
  cal: number | string
}

// ===== 常量 =====
export const MEAL_KEYS = ['breakfast', 'lunch', 'dinner', 'snack'] as const
export const MEAL_LABELS: Record<string, string> = {
  breakfast: '早餐',
  lunch: '午餐',
  dinner: '晚餐',
  snack: '加餐',
}

// ===== 库数据（模块级缓存） =====
let _lib: { foods: FoodBase[]; vessels: Record<string, VesselTpl> } | null = null

function loadLibrary(): { foods: FoodBase[]; vessels: Record<string, VesselTpl> } {
  if (_lib) return _lib
  const raw = foodLibraryJson as {
    foods: Array<{
      id: string
      name: string
      cat: string
      base: { cal: number; per: number; unit: string; protein?: number; carb?: number; fat?: number }
      pieceWeight?: number
      vessel?: string
      opts?: string[]
      img?: string
      conf?: number
    }>
    vesselTpl: Record<string, { label: string; sizes: VesselTplEntry[] }>
  }

  const foods: FoodBase[] = raw.foods.map((f) => ({
    id: f.id,
    name: f.name,
    cat: f.cat,
    kcal: f.base.cal,
    unit: f.base.unit,
    protein: f.base.protein ?? 0,
    carb: f.base.carb ?? 0,
    fat: f.base.fat ?? 0,
    pieceWeight: f.pieceWeight ?? undefined,
    vessel: f.vessel,
    opts: f.opts,
    img: f.img,
    conf: f.conf,
  }))

  // 从 vesselTpl 构建 vessels 索引（key → { label, sizes }）
  const vessels: Record<string, VesselTpl> = {}
  for (const [k, v] of Object.entries(raw.vesselTpl)) {
    vessels[k] = { label: v.label, sizes: v.sizes }
  }

  _lib = { foods, vessels }
  return _lib
}

// ===== 查询函数 =====
export const ALL_FOODS: FoodBase[] = []

// 模块加载时立即从 JSON 初始化（确保 FoodPickerSheet 等组件拿到数据）
const _lib0 = loadLibrary()
ALL_FOODS.push(..._lib0.foods)

export function getFoodById(id: string): FoodBase | undefined {
  return ALL_FOODS.find((f) => f.id === id)
}

export function vesselSizesOf(vesselKey: string): VesselTplEntry[] {
  const lib = loadLibrary()
  return lib.vessels[vesselKey]?.sizes ?? []
}

export function sweetOptsOf(sweetKey: string): OptItem[] {
  // v1.0 选项模板在 build 阶段内联，此处返回空（AddSheet 的甜度档为静态演示）
  return []
}

/** 按分类筛选食物 */
export function foodsByCat(cat: string): FoodBase[] {
  return ALL_FOODS.filter((f) => f.cat === cat)
}

/** 搜索食物（按名称） */
export function searchFoods(query: string): FoodBase[] {
  const q = query.trim().toLowerCase()
  if (!q) return ALL_FOODS
  return ALL_FOODS.filter((f) => f.name.toLowerCase().includes(q))
}

/** 计算一条记录的营养素（按实际分量缩放） */
export function computeEntry(food: FoodBase, amount: number, meal: string): FoodEntry {
  const ratio = amount / 100 // base 是每 100g/100ml
  return {
    id: `${food.id}_${Date.now()}`,
    name: food.name,
    kcal: Math.round(food.kcal * ratio),
    protein: Math.round((food.protein ?? 0) * ratio * 10) / 10,
    carb: Math.round((food.carb ?? 0) * ratio * 10) / 10,
    fat: Math.round((food.fat ?? 0) * ratio * 10) / 10,
    ts: Date.now(),
    meal,
  }
}

// ===== Store =====
interface FoodState {
  entries: FoodEntry[]
  totalCal: number
}

const state = (): FoodState => ({
  entries: [],
  totalCal: 0,
})

export const useFoodStore = defineStore('food', {
  state,
  getters: {
    mealRows(state): MealRow[] {
      return MEAL_KEYS.map((k) => {
        const entries = state.entries.filter((e) => e.meal === k)
        const cal = entries.reduce((s, e) => s + e.kcal, 0)
        return { key: k, label: MEAL_LABELS[k] ?? k, entries, cal: entries.length ? cal : '未记录' }
      })
    },

    /** 总蛋白质 (g) */
    totalProtein(state): number {
      return Math.round(state.entries.reduce((s, e) => s + (e.protein ?? 0), 0) * 10) / 10
    },

    /** 总碳水 (g) */
    totalCarbs(state): number {
      return Math.round(state.entries.reduce((s, e) => s + (e.carb ?? 0), 0) * 10) / 10
    },

    /** 总脂肪 (g) */
    totalFat(state): number {
      return Math.round(state.entries.reduce((s, e) => s + (e.fat ?? 0), 0) * 10) / 10
    },
  },
  actions: {
    addEntry(entry: FoodEntry) {
      this.entries.push(entry)
      this.totalCal += entry.kcal
    },
    removeEntry(id: string) {
      const idx = this.entries.findIndex((e) => e.id === id)
      if (idx >= 0) {
        this.totalCal -= this.entries[idx].kcal
        this.entries.splice(idx, 1)
      }
    },
    clearToday() {
      this.entries = []
      this.totalCal = 0
    },

    /** 初始化：从 JSON 加载 347 条食物库 */
    initLibrary() {
      const lib = loadLibrary()
      ALL_FOODS.length = 0
      ALL_FOODS.push(...lib.foods)
    },
  },
})